(window.__APPSRC=window.__APPSRC||{})["xmvkq4zed--zb-sj-prepa-chir-j1-ide"]="{\n \"app\": \"xmvkq4zed\",\n \"id\": \"zb-sj-prepa-chir-j1-ide\",\n \"titre\": \"Préparation D.E (J) · J1 Chirurgie IDE\",\n \"session\": \"J\",\n \"annee\": 2026,\n \"nq\": 49,\n \"nsuj\": 1,\n \"origines\": [\n  {\n   \"fichier\": \"prepa-de-2026/J1_CHIRURGIE_IDE_corrige_explique.pdf\",\n   \"sha256\": \"208d6a43bcf5d25965c93f89b74d4dd0edac9de9388ef98aad0fd42a1edb1be4\"\n  }\n ],\n \"antennes\": [\n  {\n   \"name\": \"J DE PRÉPARATION AU D.E\",\n   \"slug\": \"j-preparation-de\",\n   \"session\": \"J\",\n   \"annee\": 2026,\n   \"existe\": true,\n   \"sujets\": [\n    {\n     \"name\": \"J Chirurgie · Prépa D.E J1 (IDE) · J1 et J7 identiques\",\n     \"slug\": \"prepa-chir-j1-ide\",\n     \"pages\": \"\",\n     \"count\": 49,\n     \"session\": \"J\",\n     \"annee\": 2026,\n     \"matiere\": \"Chirurgie\",\n     \"source\": \"J1_CHIRURGIE_IDE_corrige_explique.pdf\",\n     \"questions\": [\n      {\n       \"id\": \"j-preparation-de__prepa-chir-j1-ide__0\",\n       \"num\": \"1\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"La hernie n'existe pas chez la femme\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. Faux\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"La hernie existe chez la femme. La hernie crurale survient surtout chez la femme de 30 à 60 ans, et la hernie ombilicale de l'adulte s'observe surtout chez la femme.\\n\\nSource : Cours L2 IDE « Prise en charge infirmière des pathologies chirurgicales » (licence 2 ide.pdf), Hernies, 2.2 Hernie crurale ; Cours de chirurgie traumatique et digestif.pptx, Hernies, VII\",\n       \"sourceDoc\": \"Préparation D.E (J) · J1 Chirurgie IDE\",\n       \"sourceFile\": \"J1_CHIRURGIE_IDE_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-chir-j1-ide__1\",\n       \"num\": \"2\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Le signe de l'épaulette est la conséquence de la vacuité de la glène dans la luxation de l'épaule\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Vrai\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"Dans la luxation antéro-interne, la tête humérale quitte la glène. La palpation trouve la vacuité de la cavité glénoïde, et la saillie de l'acromion devient visible : c'est le signe de l'épaulette.\\n\\nSource : Traumatologie Complet-2.pdf, Luxation de l'épaule, 3.2.3 Signes physiques (inspection et palpation)\",\n       \"sourceDoc\": \"Préparation D.E (J) · J1 Chirurgie IDE\",\n       \"sourceFile\": \"J1_CHIRURGIE_IDE_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-chir-j1-ide__2\",\n       \"num\": \"3\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Le syndrome de Wolkmann siège sur les membres inférieurs\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. Faux\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"Le syndrome de Volkmann frappe les muscles de l'avant-bras (longs fléchisseurs des doigts), surtout après les fractures du coude et de l'avant-bras chez l'enfant. Il ne siège pas aux membres inférieurs.\\n\\nSource : Traumatologie Complet-2.pdf, Fractures des deux os de l'avant-bras, V. Le syndrome de Wolkmann\",\n       \"sourceDoc\": \"Préparation D.E (J) · J1 Chirurgie IDE\",\n       \"sourceFile\": \"J1_CHIRURGIE_IDE_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-chir-j1-ide__3\",\n       \"num\": \"4\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Les fractures pathologiques surviennent à la suite des traumatismes minimes\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Vrai\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"« Certaines fractures surviennent à la suite d'un traumatisme minime : on parle de fractures pathologiques. »\\n\\nSource : Pathologie chirurgicale – Sémiologie L1 (PATHOLOGIE CHIRUR-SEMIO L1), Généralités sur les fractures, I. Définition\",\n       \"sourceDoc\": \"Préparation D.E (J) · J1 Chirurgie IDE\",\n       \"sourceFile\": \"J1_CHIRURGIE_IDE_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-chir-j1-ide__4\",\n       \"num\": \"5\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Le volet costal est une fracture étagée\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Vrai\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"Le volet costal : deux traits de fracture sur une même côte isolent un fragment intermédiaire mobile. Deux traits délimitant un 3e fragment définissent la fracture à étage.\\n\\nSource : Cours de chirurgie traumatique et digestif.pptx, Traumatisme du thorax (volet costal) ; Pathologie chirurgicale – Sémiologie L1 (PATHOLOGIE CHIRUR-SEMIO L1), Généralités sur les fractures (fracture à étage)\",\n       \"sourceDoc\": \"Préparation D.E (J) · J1 Chirurgie IDE\",\n       \"sourceFile\": \"J1_CHIRURGIE_IDE_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-chir-j1-ide__5\",\n       \"num\": \"6\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Le signe de Rovsing positif est la mise en évidence du signe pathognomonique de l'appendicite\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Vrai\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"Le signe de Rovsing (douleur en fosse iliaque droite à la palpation du flanc gauche) oriente vers l'appendicite. Le cours le cite parmi les signes de l'appendicite. (explication hors cours du projet) pour le caractère « pathognomonique ». Remarque : Le cours cite le signe de Rovsing sans le qualifier de pathognomonique.\\n\\nSource : Cours L2 IDE « Prise en charge infirmière des pathologies chirurgicales » (licence 2 ide.pdf), Appendicite aiguë, formes cliniques (Guinard, Rovsing, Blumberg)\",\n       \"sourceDoc\": \"Préparation D.E (J) · J1 Chirurgie IDE\",\n       \"sourceFile\": \"J1_CHIRURGIE_IDE_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-chir-j1-ide__6\",\n       \"num\": \"7\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"L'occlusion haute siège sur l'œsophage\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. Faux\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"L'occlusion intestinale est un arrêt du transit dans un segment de l'intestin. L'occlusion haute siège sur le grêle, pas sur l'œsophage.\\n\\nSource : Cours L2 IDE « Prise en charge infirmière des pathologies chirurgicales » (licence 2 ide.pdf), Occlusions intestinales aiguës (définition et diagnostic du siège)\",\n       \"sourceDoc\": \"Préparation D.E (J) · J1 Chirurgie IDE\",\n       \"sourceFile\": \"J1_CHIRURGIE_IDE_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-chir-j1-ide__7\",\n       \"num\": \"8\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"La tuméfaction de l'étranglement herniaire est dure, réductible et impulsive à la toux\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. Faux\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"Dans l'étranglement, la tuméfaction est dure, tendue, douloureuse, IRréductible, non impulsive et non expansive à la toux.\\n\\nSource : Cours L2 IDE « Prise en charge infirmière des pathologies chirurgicales » (licence 2 ide.pdf), Hernies, 4.2 Hernie compliquée (étranglement)\",\n       \"sourceDoc\": \"Préparation D.E (J) · J1 Chirurgie IDE\",\n       \"sourceFile\": \"J1_CHIRURGIE_IDE_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-chir-j1-ide__8\",\n       \"num\": \"9\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"L'adénome de la prostate est une maladie bénigne\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Vrai\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"« L'adénome de la prostate est une tumeur bénigne qui se traduit par une hyperplasie et une hypertrophie de la glande prostatique. »\\n\\nSource : Cours de chirurgie traumatique et digestif.pptx, Adénome de la prostate, I. Définition\",\n       \"sourceDoc\": \"Préparation D.E (J) · J1 Chirurgie IDE\",\n       \"sourceFile\": \"J1_CHIRURGIE_IDE_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-chir-j1-ide__9\",\n       \"num\": \"10\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Le mal de Pott est une infection disco-vertébrale due au staphylocoque aureus\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. Faux\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"Le mal de Pott est la tuberculose disco-vertébrale, due au bacille de Koch. Le staphylocoque donne les ostéomyélites vertébrales (diagnostic différentiel).\\n\\nSource : Neurochorurgie.pdf, Mal de Pott, introduction ; Cours de chirurgie traumatique et digestif.pptx, Mal de Pott (diagnostic différentiel)\",\n       \"sourceDoc\": \"Préparation D.E (J) · J1 Chirurgie IDE\",\n       \"sourceFile\": \"J1_CHIRURGIE_IDE_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-chir-j1-ide__10\",\n       \"num\": \"11\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Le traitement de l'appendicite est uniquement chirurgical\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. Faux\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"Le traitement est surtout chirurgical (appendicectomie). Le cours prévoit aussi un volet médical : apport hydrique, antalgiques, antibiotiques, et un traitement médical de « refroidissement » du plastron avant l'opération.\\n\\nSource : Cours L2 IDE « Prise en charge infirmière des pathologies chirurgicales » (licence 2 ide.pdf), Appendicite aiguë, IX. Traitement (moyens médicaux, plastron)\",\n       \"sourceDoc\": \"Préparation D.E (J) · J1 Chirurgie IDE\",\n       \"sourceFile\": \"J1_CHIRURGIE_IDE_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-chir-j1-ide__11\",\n       \"num\": \"12\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Le signe capital de la péritonite est la contracture abdominale\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Vrai\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"Dans la péritonite par perforation, le maître signe est la contracture abdominale, qui peut aller jusqu'au « ventre de bois ».\\n\\nSource : Cours L2 IDE « Prise en charge infirmière des pathologies chirurgicales » (licence 2 ide.pdf), Péritonites (contracture à la palpation) et Contusions abdominales (2.2 Tableau de péritonite)\",\n       \"sourceDoc\": \"Préparation D.E (J) · J1 Chirurgie IDE\",\n       \"sourceFile\": \"J1_CHIRURGIE_IDE_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-chir-j1-ide__12\",\n       \"num\": \"13\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Les occlusions fonctionnelles sont le fait du dérèglement du système nerveux intestinal\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Vrai\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"Les occlusions fonctionnelles relèvent du dérèglement du système nerveux intestinal (paralysie ou spasmes).\\n\\nSource : Cours L2 IDE « Prise en charge infirmière des pathologies chirurgicales » (licence 2 ide.pdf), Occlusions intestinales aiguës, 1.2 Occlusions fonctionnelles\",\n       \"sourceDoc\": \"Préparation D.E (J) · J1 Chirurgie IDE\",\n       \"sourceFile\": \"J1_CHIRURGIE_IDE_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-chir-j1-ide__13\",\n       \"num\": \"14\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"La femme n'a pas d'urètre\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. Faux\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"La femme a un urètre : court (3 à 4 cm) et droit, il s'ouvre dans la vulve entre le clitoris et l'orifice vaginal.\\n\\nSource : Cours de chirurgie traumatique et digestif.pptx, Rétrécissement de l'urètre, II. Anatomo-physiopathologie\",\n       \"sourceDoc\": \"Préparation D.E (J) · J1 Chirurgie IDE\",\n       \"sourceFile\": \"J1_CHIRURGIE_IDE_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-chir-j1-ide__14\",\n       \"num\": \"15\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Les brûlures provoquées par contact sont plus graves que celles faites par rayonnement\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. Faux\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"Le cours distingue brûlures par contact et brûlures par rayonnement et précise : « Quel qu'en soit le type, les brûlures sont généralement graves. » La gravité dépend de la surface, de la profondeur, de la localisation et du terrain, pas du seul mode de contact.\\n\\nSource : Pathologie chirurgicale – Sémiologie L1 (PATHOLOGIE CHIRUR-SEMIO L1), Brûlures 1, II. Étiologie et 3-3 Les brûlures graves\",\n       \"sourceDoc\": \"Préparation D.E (J) · J1 Chirurgie IDE\",\n       \"sourceFile\": \"J1_CHIRURGIE_IDE_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-chir-j1-ide__15\",\n       \"num\": \"16\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"La ponction sus-pubienne est conditionnée par l'impossibilité d'une pose de sonde vésicale\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Vrai\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"Devant une rétention, « si le sondage vésical est impossible, il faut pratiquer une ponction sus-pubienne ».\\n\\nSource : Cours de chirurgie traumatique et digestif.pptx, Rétrécissement de l'urètre, 7-3 Conduite à tenir ; Rétention urinaire (drainage vésical)\",\n       \"sourceDoc\": \"Préparation D.E (J) · J1 Chirurgie IDE\",\n       \"sourceFile\": \"J1_CHIRURGIE_IDE_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-chir-j1-ide__16\",\n       \"num\": \"17\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"L'embarrure est une fracture du crâne caractérisée par l'enfoncement d'un fragment osseux vers l'intérieur de la boîte crânienne\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Vrai\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"La fracture de la voûte peut être « simple ou avec embarrure » : un fragment osseux est enfoncé vers l'intérieur du crâne. Le traitement consiste à le remonter à son niveau initial.\\n\\nSource : Cours de chirurgie traumatique et digestif.pptx, Traumatismes crâniens, IV-B Lésions osseuses ; NEUROCHIRURGIE L3.pptx (embarrure)\",\n       \"sourceDoc\": \"Préparation D.E (J) · J1 Chirurgie IDE\",\n       \"sourceFile\": \"J1_CHIRURGIE_IDE_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-chir-j1-ide__17\",\n       \"num\": \"18\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Plus le score de Glasgow est élevé plus l'état du malade est grabataire\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. Faux\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"Un Glasgow élevé traduit un bon état neurologique (13–15 = bénin) ; un Glasgow bas (3–8) traduit un traumatisme grave.\\n\\nSource : NEUROCHIRURGIE L3.pptx, niveaux de gravité\",\n       \"sourceDoc\": \"Préparation D.E (J) · J1 Chirurgie IDE\",\n       \"sourceFile\": \"J1_CHIRURGIE_IDE_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-chir-j1-ide__18\",\n       \"num\": \"19\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"L'hématome extradural ou épidural est une collection sanguine développée entre la dure-mère et l'os du crâne\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Vrai\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"L'hématome extradural est une collection de sang entre la dure-mère et la face interne de l'os du crâne. (explication hors cours du projet) pour la définition exacte ; le cours décrit l'intervalle libre et les signes.\\n\\nSource : Cours de chirurgie traumatique et digestif.pptx, Traumatismes crâniens, VI. Hématome extradural ; ANATOMIE LIVRE 2023-2024 OK.pdf (dure-mère accolée à l'os)\",\n       \"sourceDoc\": \"Préparation D.E (J) · J1 Chirurgie IDE\",\n       \"sourceFile\": \"J1_CHIRURGIE_IDE_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-chir-j1-ide__19\",\n       \"num\": \"20\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Le pied bot équin est une déformation dont la pointe du pied est orienté vers le bas\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Vrai\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"Dans le pied bot équin, l'équinisme est la flexion forcée du pied qui abaisse la pointe et relève le talon.\\n\\nSource : Pathologie chirurgicale – Sémiologie L1 (PATHOLOGIE CHIRUR-SEMIO L1), Pieds bots congénitaux, III. Le pied bot varus équin II. QCM / QRU\",\n       \"sourceDoc\": \"Préparation D.E (J) · J1 Chirurgie IDE\",\n       \"sourceFile\": \"J1_CHIRURGIE_IDE_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-chir-j1-ide__20\",\n       \"num\": \"21\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Parmi les propositions suivantes, indiquez celle qui se rapporte à la notion d'intervalle de temps libre chez le traumatisé crânien\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"A. Le temps qui s'écoule entre la survenue de l'accident et la prise en charge du patient\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"B. Le temps qui sépare la perte de connaissance initiale et la réapparition des troubles de la conscience\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"C. La durée des troubles de la conscience occasionnée par le traumatisme crânien\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. B. Le temps qui sépare la perte de connaissance initiale et la réapparition des troubles de la conscience\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"L'intervalle libre est le temps pendant lequel le blessé paraît s'améliorer après le traumatisme, avant que son état ne s'aggrave de nouveau.\\n\\nSource : Cours de chirurgie traumatique et digestif.pptx, Traumatismes crâniens, VI. Hématome extradural\",\n       \"sourceDoc\": \"Préparation D.E (J) · J1 Chirurgie IDE\",\n       \"sourceFile\": \"J1_CHIRURGIE_IDE_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-chir-j1-ide__21\",\n       \"num\": \"22\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Identifiez dans les items ci-dessous les signes du syndrome de Wolkmann ?\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"A. Œdème de la jambe\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"B. Douleur intense\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"C. Nausées et vomissements\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"D. Pâleur et froideur des doigts\"\n        },\n        {\n         \"letter\": \"E\",\n         \"text\": \"E. Hyperthermie\"\n        },\n        {\n         \"letter\": \"F\",\n         \"text\": \"F. Engourdissement ou picotement des doigts\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": true,\n       \"answer\": \"B. B. Douleur intense ; D. D. Pâleur et froideur des doigts ; F. F. Engourdissement ou picotement des doigts\",\n       \"answerLetters\": [\n        \"B\",\n        \"D\",\n        \"F\"\n       ],\n       \"explanation\": \"Volkmann : douleur plus ou moins vive, œdème, cyanose, froideur des extrémités et troubles sensitifs (engourdissement, picotements). Nausées et hyperthermie n'en font pas partie. Remarque : Le cours cite aussi l'œdème parmi les signes du syndrome de Volkmann.\\n\\nSource : Traumatologie Complet-2.pdf, Syndrome de Wolkmann (5.2) et Rôle de l'infirmier dans la surveillance du plâtre (7.1)\",\n       \"sourceDoc\": \"Préparation D.E (J) · J1 Chirurgie IDE\",\n       \"sourceFile\": \"J1_CHIRURGIE_IDE_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-chir-j1-ide__22\",\n       \"num\": \"23\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Deux items ne font pas partie des étiologies de l'appendicite aigüe parmi ceux qui sont énumérés en dessous. Lesquels ? (2 réponses)\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"A. Infections gastro-intestinales\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"B. Hernie discale\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"C. Parasitoses intestinales\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"D. Corps étrangers\"\n        },\n        {\n         \"letter\": \"E\",\n         \"text\": \"E. Fécalome\"\n        },\n        {\n         \"letter\": \"F\",\n         \"text\": \"F. Alimentation pauvre en viande\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": true,\n       \"answer\": \"B. B. Hernie discale ; F. F. Alimentation pauvre en viande\",\n       \"answerLetters\": [\n        \"B\",\n        \"F\"\n       ],\n       \"explanation\": \"Étiologies de l'appendicite : infection de la flore intestinale, parasites, corps étrangers, stercolithe (fécalome)… La hernie discale et une alimentation pauvre en viande n'en font pas partie.\\n\\nSource : Cours L2 IDE « Prise en charge infirmière des pathologies chirurgicales » (licence 2 ide.pdf), Appendicite aiguë, III. Pathogénie ; Cours de chirurgie traumatique et digestif.pptx, III. Étiologies\",\n       \"sourceDoc\": \"Préparation D.E (J) · J1 Chirurgie IDE\",\n       \"sourceFile\": \"J1_CHIRURGIE_IDE_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-chir-j1-ide__23\",\n       \"num\": \"24\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"La liste ci-dessous est celle des signes fonctionnels de la fracture ; lesquels ? (2 réponses)\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"A. Crépitation osseuse\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"B. Douleur vive\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"C. Déformation du membre\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"D. Impotence fonctionnelle\"\n        },\n        {\n         \"letter\": \"E\",\n         \"text\": \"E. Mobilité anormale du membre atteint\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": true,\n       \"answer\": \"B. B. Douleur vive ; D. D. Impotence fonctionnelle\",\n       \"answerLetters\": [\n        \"B\",\n        \"D\"\n       ],\n       \"explanation\": \"Signes fonctionnels d'une fracture : douleur vive et impotence fonctionnelle. Crépitation, déformation et mobilité anormale se découvrent à l'examen : ce sont des signes physiques.\\n\\nSource : Traumatologie Complet-2.pdf, Fractures de l'humérus (4.1 signes fonctionnels) ; Fractures du fémur (2.1)\",\n       \"sourceDoc\": \"Préparation D.E (J) · J1 Chirurgie IDE\",\n       \"sourceFile\": \"J1_CHIRURGIE_IDE_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-chir-j1-ide__24\",\n       \"num\": \"25\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Sur le lieu de l'accident, certains gestes suivants sont proscrits en cas de fracture du fémur ; lesquels ? (2 réponses)\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"A. Préparer psychologiquement le blessé à l'intervention\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"B. Immobiliser dans une gouttière le membre atteint\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"C. Chercher à réduire une fracture ouverte\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"D. Laisser le blessé couché par terre\"\n        },\n        {\n         \"letter\": \"E\",\n         \"text\": \"E. Baliser l'emplacement du patient\"\n        },\n        {\n         \"letter\": \"F\",\n         \"text\": \"F. Faire des manœuvres ou des mobilisations intempestives\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": true,\n       \"answer\": \"C. C. Chercher à réduire une fracture ouverte ; F. F. Faire des manœuvres ou des mobilisations intempestives\",\n       \"answerLetters\": [\n        \"C\",\n        \"F\"\n       ],\n       \"explanation\": \"Sur les lieux d'une fracture : pas de manœuvres ou de mobilisations intempestives et « surtout ne pas chercher à réduire une fracture ouverte ». Immobiliser et baliser sont au contraire recommandés.\\n\\nSource : Traumatologie Complet-2.pdf, 8.1 Soins sur les lieux de l'accident\",\n       \"sourceDoc\": \"Préparation D.E (J) · J1 Chirurgie IDE\",\n       \"sourceFile\": \"J1_CHIRURGIE_IDE_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-chir-j1-ide__25\",\n       \"num\": \"26\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Parmi les éléments de la surveillance post opératoire ci-dessous, trois (3) relèvent de l'état végétatif du patient. Lesquels ?\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"A. Perméabilité des tuyaux\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"B. Fréquence respiratoire\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"C. Pression artérielle\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"D. Profondeur du coma\"\n        },\n        {\n         \"letter\": \"E\",\n         \"text\": \"E. Niveau de conscience\"\n        },\n        {\n         \"letter\": \"F\",\n         \"text\": \"F. Fréquence cardiaque\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": true,\n       \"answer\": \"B. B. Fréquence respiratoire ; C. C. Pression artérielle ; F. F. Fréquence cardiaque\",\n       \"answerLetters\": [\n        \"B\",\n        \"C\",\n        \"F\"\n       ],\n       \"explanation\": \"La surveillance de l'« état végétatif » porte sur le pouls, la tension artérielle, le rythme cardiaque et respiratoire. Conscience et profondeur du coma relèvent de l'état neurologique.\\n\\nSource : Neurochorurgie.pdf, Traumatismes crâniens, 4.5 Soins post-opératoires\",\n       \"sourceDoc\": \"Préparation D.E (J) · J1 Chirurgie IDE\",\n       \"sourceFile\": \"J1_CHIRURGIE_IDE_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-chir-j1-ide__26\",\n       \"num\": \"27\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Les items ci-dessous font partie des étiologies de l'appendicite aigüe exceptés deux ; lesquels ? (2 réponses)\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"A. Infections gastro-intestinales\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"B. Alimentation pauvre en viande\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"C. Parasitoses intestinales\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"D. Corps étrangers\"\n        },\n        {\n         \"letter\": \"E\",\n         \"text\": \"E. Hernie discale\"\n        },\n        {\n         \"letter\": \"F\",\n         \"text\": \"F. Fécalome\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": true,\n       \"answer\": \"B. B. Alimentation pauvre en viande ; E. E. Hernie discale\",\n       \"answerLetters\": [\n        \"B\",\n        \"E\"\n       ],\n       \"explanation\": \"Même question que la n°23, avec les options dans un autre ordre : hernie discale et alimentation pauvre en viande ne sont pas des étiologies de l'appendicite. Remarque : Question en double dans le sujet (n°23 et n°27).\\n\\nSource : Cours L2 IDE « Prise en charge infirmière des pathologies chirurgicales » (licence 2 ide.pdf), Appendicite aiguë, III. Pathogénie\",\n       \"sourceDoc\": \"Préparation D.E (J) · J1 Chirurgie IDE\",\n       \"sourceFile\": \"J1_CHIRURGIE_IDE_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-chir-j1-ide__27\",\n       \"num\": \"28\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Parmi les actions suivantes, indiquez les deux à effectuer en urgence chez un patient qui souffre de rétention urinaire\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"A. L'adénomectomie\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"B. La cystectomie\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"C. La ponction sus-pubienne\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"D. Le sondage urétral\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": true,\n       \"answer\": \"C. C. La ponction sus-pubienne ; D. D. Le sondage urétral\",\n       \"answerLetters\": [\n        \"C\",\n        \"D\"\n       ],\n       \"explanation\": \"Devant une rétention urinaire, le drainage vésical est une urgence : sondage urétral ou ponction sus-pubienne.\\n\\nSource : Cours de chirurgie traumatique et digestif.pptx, Rétention urinaire, IV. Traitement\",\n       \"sourceDoc\": \"Préparation D.E (J) · J1 Chirurgie IDE\",\n       \"sourceFile\": \"J1_CHIRURGIE_IDE_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-chir-j1-ide__28\",\n       \"num\": \"29\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Parmi les propositions suivantes, indiquez celle qui correspond au score de Glasgow pendant un traumatisme crânien grave\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"A. 13 à 15\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"B. 9 à 12\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"C. 3 à 8\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"C. C. 3 à 8\",\n       \"answerLetters\": [\n        \"C\"\n       ],\n       \"explanation\": \"Traumatisme crânien grave : Glasgow de 3 à 8.\\n\\nSource : NEUROCHIRURGIE L3.pptx, niveaux de gravité\",\n       \"sourceDoc\": \"Préparation D.E (J) · J1 Chirurgie IDE\",\n       \"sourceFile\": \"J1_CHIRURGIE_IDE_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-chir-j1-ide__29\",\n       \"num\": \"30\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Parmi les propositions suivantes, indiquez les deux (02) soins préopératoires chez le traumatisé crânien\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"A. Le rasage soigneux de la zone d'intervention du cuir chevelu\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"B. Le rasage soigneux de la totalité du cuir chevelu\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"C. La mise en place d'une ou deux voies veineuses aux membres supérieurs\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"D. Le rasage soigneux de toutes les zones de pilosité\"\n        },\n        {\n         \"letter\": \"E\",\n         \"text\": \"E. L'embellissement du crâne\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": true,\n       \"answer\": \"B. B. Le rasage soigneux de la totalité du cuir chevelu ; C. C. La mise en place d'une ou deux voies veineuses aux membres supérieurs\",\n       \"answerLetters\": [\n        \"B\",\n        \"C\"\n       ],\n       \"explanation\": \"Avant l'opération du TC : rasage soigneux de la totalité du cuir chevelu, et mise en place d'une ou deux voies veineuses aux membres supérieurs.\\n\\nSource : NEUROCHIRURGIE L3.pptx, Traumatismes crâniens, 4.3 Soins pré-opératoires et 4.4 Traitement chirurgical\",\n       \"sourceDoc\": \"Préparation D.E (J) · J1 Chirurgie IDE\",\n       \"sourceFile\": \"J1_CHIRURGIE_IDE_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-chir-j1-ide__30\",\n       \"num\": \"31\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Parmi les éléments suivants, indiquez les deux (02) signes physiques de la rétention urinaire aigüe\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"A. Le besoin impérieux d'uriner\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"B. La douleur à la palpation\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"C. La masse hypogastrique\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"D. L'impossibilité d'uriner\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": true,\n       \"answer\": \"B. B. La douleur à la palpation ; C. C. La masse hypogastrique\",\n       \"answerLetters\": [\n        \"B\",\n        \"C\"\n       ],\n       \"explanation\": \"Signes physiques du globe vésical : masse hypogastrique et douleur à la palpation augmentant le besoin d'uriner. L'impossibilité d'uriner et le besoin impérieux sont des signes fonctionnels.\\n\\nSource : Cours de chirurgie traumatique et digestif.pptx, Rétention urinaire, 1-2 Clinique\",\n       \"sourceDoc\": \"Préparation D.E (J) · J1 Chirurgie IDE\",\n       \"sourceFile\": \"J1_CHIRURGIE_IDE_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-chir-j1-ide__31\",\n       \"num\": \"32\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"L'abcès froid est une collection purulente chronique causée par quel germe ?\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"A. Le streptocoque\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"B. Le staphylocoque doré ou blanc\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"C. Le bacille de Koch\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"D. Le gonocoque\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"C. C. Le bacille de Koch\",\n       \"answerLetters\": [\n        \"C\"\n       ],\n       \"explanation\": \"L'abcès froid est le plus souvent d'origine tuberculeuse (bacille de Koch).\\n\\nSource : Pathologie chirurgicale – Sémiologie L1 (PATHOLOGIE CHIRUR-SEMIO L1), Abcès froid, II. Étiologies\",\n       \"sourceDoc\": \"Préparation D.E (J) · J1 Chirurgie IDE\",\n       \"sourceFile\": \"J1_CHIRURGIE_IDE_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-chir-j1-ide__32\",\n       \"num\": \"33\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Parmi les éléments suivants indiquez les deux (02) précautions à prendre avant la pose d'une poche de sang\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"A. Faire le test de compatibilité\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"B. Bien régler le débit de la transfusion\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"C. Alimenter correctement le patient\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"D. Vérifier l'écoulement du sang\"\n        },\n        {\n         \"letter\": \"E\",\n         \"text\": \"E. S'assurer que la malade n'a pas de besoin urgent à satisfaire\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": true,\n       \"answer\": \"A. A. Faire le test de compatibilité ; E. E. S'assurer que la malade n'a pas de besoin urgent à satisfaire\",\n       \"answerLetters\": [\n        \"A\",\n        \"E\"\n       ],\n       \"explanation\": \"Avant de poser la poche : faire le test de compatibilité (contrôle ultime) et s'assurer que le patient n'a pas un besoin urgent à satisfaire, car il restera longtemps perfusé. (explication hors cours du projet)\\n\\nSource : —\",\n       \"sourceDoc\": \"Préparation D.E (J) · J1 Chirurgie IDE\",\n       \"sourceFile\": \"J1_CHIRURGIE_IDE_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-chir-j1-ide__33\",\n       \"num\": \"34\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Parmi ces propositions, indiquez l'ordre chronologique de préparation d'un champ opératoire\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"A. Rasage / Détersion / désinfection\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"B. Détersion / rasage/ désinfection\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"C. Désinfection / rasage/ Détersion\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. B. Détersion / rasage/ désinfection\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"Préparation du champ opératoire : savonnage large provoquant une détersion de la peau, puis rasage, puis désinfection (badigeonnage antiseptique).\\n\\nSource : Techniques de soins infirmiers spécialisés en chirurgie, L3 (TECHNIQUES DE SOINS INFIRMIERS SPECIALISÉS EN CHIRURGIE.pdf), L'intervention chirurgicale, 2. Préparation locale ; Traumatologie Complet-2.pdf, 8.2.2.5\",\n       \"sourceDoc\": \"Préparation D.E (J) · J1 Chirurgie IDE\",\n       \"sourceFile\": \"J1_CHIRURGIE_IDE_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-chir-j1-ide__34\",\n       \"num\": \"35\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Relever parmi ces propositions trois (03) localisations de gravité d'une brûlure\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"A. Les parties génitales\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"B. La profondeur\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"C. La surface corporelle brûlée\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"D. Les extrémités\"\n        },\n        {\n         \"letter\": \"E\",\n         \"text\": \"E. Le terrain\"\n        },\n        {\n         \"letter\": \"F\",\n         \"text\": \"F. Les plis de flexion\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": true,\n       \"answer\": \"B. B. La profondeur ; D. D. Les extrémités ; E. E. Le terrain\",\n       \"answerLetters\": [\n        \"B\",\n        \"D\",\n        \"E\"\n       ],\n       \"explanation\": \"Les extrémités (mains, pieds) sont une localisation de gravité : risque d'amputation des doigts et des orteils.\\n\\nSource : COURS PATHOLOGIE CHIRURGICALE SEMIOLOGIE (L1 IDE-SF), chapitre Brûlures, p. 85-101 (3-3 Les brûlures graves ; 4.6 Localisation)\",\n       \"sourceDoc\": \"Préparation D.E (J) · J1 Chirurgie IDE\",\n       \"sourceFile\": \"J1_CHIRURGIE_IDE_corrige_explique.pdf\",\n       \"sourcePage\": null,\n       \"off\": true\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-chir-j1-ide__35\",\n       \"num\": \"36\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"La rétention aiguë est caractérisée par quoi ? (Choisir la bonne réponse)\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"A. Impossibilité de vider totalement la vessie\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"B. Impossibilité brutale et totale d'émettre des urines\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"C. Impossibilité brutale et totale de vider totalement la vessie.\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. B. Impossibilité brutale et totale d'émettre des urines\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"« La rétention aiguë ou complète se traduit par l'impossibilité brutale et totale d'uriner ou d'émettre des urines. » L'impossibilité de vider totalement la vessie définit la rétention chronique.\\n\\nSource : Cours de chirurgie traumatique et digestif.pptx, Rétention urinaire, 1-1 et 2-1 Définitions III. ÉTUDE DE CAS N°1\",\n       \"sourceDoc\": \"Préparation D.E (J) · J1 Chirurgie IDE\",\n       \"sourceFile\": \"J1_CHIRURGIE_IDE_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-chir-j1-ide__36\",\n       \"num\": \"37\",\n       \"type\": \"CAS_CLINIQUE\",\n       \"typeLabel\": \"Étude de cas / Cas clinique\",\n       \"partieTitle\": \"Cas clinique\",\n       \"caseTitle\": \"Cas clinique\",\n       \"caseData\": \"ÉTUDE DE CAS N°1 — L'enfant KONAN Fréjus 15 ANS tombe d'un manguier. On constate qu'il ne peut mouvoir ni les deux membres supérieurs ni les deux membres inférieurs.\",\n       \"text\": \"Nommez cette présentation clinique (1 réponse)\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"A. Monoplégie\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"B. Paraplégie\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"C. Tétraplégie\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"C. C. Tétraplégie\",\n       \"answerLetters\": [\n        \"C\"\n       ],\n       \"explanation\": \"Les quatre membres sont paralysés : c'est une tétraplégie.\\n\\nSource : Neurochorurgie.pdf, Fracture du rachis (examen de la motricité)\",\n       \"sourceDoc\": \"Préparation D.E (J) · J1 Chirurgie IDE\",\n       \"sourceFile\": \"J1_CHIRURGIE_IDE_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-chir-j1-ide__37\",\n       \"num\": \"38\",\n       \"type\": \"CAS_CLINIQUE\",\n       \"typeLabel\": \"Étude de cas / Cas clinique\",\n       \"partieTitle\": \"Cas clinique\",\n       \"caseTitle\": \"Cas clinique\",\n       \"caseData\": \"ÉTUDE DE CAS N°1 — L'enfant KONAN Fréjus 15 ANS tombe d'un manguier. On constate qu'il ne peut mouvoir ni les deux membres supérieurs ni les deux membres inférieurs.\",\n       \"text\": \"Identifiez le segment du rachis atteint (1 réponse)\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"A. Segment cervical\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"B. Segment coxal\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"C. Segment lombaire\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. A. Segment cervical\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"Une atteinte médullaire du rachis cervical donne une tétraplégie.\\n\\nSource : Cours de chirurgie traumatique et digestif.pptx, Fractures du rachis, IV-2 Symptômes neurologiques\",\n       \"sourceDoc\": \"Préparation D.E (J) · J1 Chirurgie IDE\",\n       \"sourceFile\": \"J1_CHIRURGIE_IDE_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-chir-j1-ide__38\",\n       \"num\": \"39\",\n       \"type\": \"CAS_CLINIQUE\",\n       \"typeLabel\": \"Étude de cas / Cas clinique\",\n       \"partieTitle\": \"Cas clinique\",\n       \"caseTitle\": \"Cas clinique\",\n       \"caseData\": \"ÉTUDE DE CAS N°1 — L'enfant KONAN Fréjus 15 ANS tombe d'un manguier. On constate qu'il ne peut mouvoir ni les deux membres supérieurs ni les deux membres inférieurs.\",\n       \"text\": \"Enumérez les lésions possibles ayant entraîné cet état (3 réponses)\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"A. Traumatisme crânien\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"B. Traumatisme thoracique\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"C. Fractures ou luxations cervicales\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"D. Traumatismes médullaires\"\n        },\n        {\n         \"letter\": \"E\",\n         \"text\": \"E. Compression médullaire\"\n        },\n        {\n         \"letter\": \"F\",\n         \"text\": \"F. Traumatisme du bassin\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": true,\n       \"answer\": \"C. C. Fractures ou luxations cervicales ; D. D. Traumatismes médullaires ; E. E. Compression médullaire\",\n       \"answerLetters\": [\n        \"C\",\n        \"D\",\n        \"E\"\n       ],\n       \"explanation\": \"Après une chute avec tétraplégie, on suspecte des lésions du rachis cervical : fracture ou luxation cervicale, avec atteinte de la moelle (traumatisme médullaire, compression médullaire).\\n\\nSource : Cours de chirurgie traumatique et digestif.pptx, Fractures du rachis, III. Anatomie pathologique (compression, section)\",\n       \"sourceDoc\": \"Préparation D.E (J) · J1 Chirurgie IDE\",\n       \"sourceFile\": \"J1_CHIRURGIE_IDE_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-chir-j1-ide__39\",\n       \"num\": \"40\",\n       \"type\": \"CAS_CLINIQUE\",\n       \"typeLabel\": \"Étude de cas / Cas clinique\",\n       \"partieTitle\": \"Cas clinique\",\n       \"caseTitle\": \"Cas clinique\",\n       \"caseData\": \"ÉTUDE DE CAS N°1 — L'enfant KONAN Fréjus 15 ANS tombe d'un manguier. On constate qu'il ne peut mouvoir ni les deux membres supérieurs ni les deux membres inférieurs.\",\n       \"text\": \"Dans la conduite du rôle de l'infirmier dans les soins à apporter en vue d'éviter les escarres pour cette présentation ; lequel n'en fait pas partie ?\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"A. Changement de position toutes les 2 heures\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"B. Réfection de lit dès que souillé\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"C. Sonde à demeure\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"D. Toilette générale\"\n        },\n        {\n         \"letter\": \"E\",\n         \"text\": \"E. Sonde nasogastrique pour l'alimentation\"\n        },\n        {\n         \"letter\": \"F\",\n         \"text\": \"F. Utiliser des produits irritants sur la peau\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"F. F. Utiliser des produits irritants sur la peau\",\n       \"answerLetters\": [\n        \"F\"\n       ],\n       \"explanation\": \"La prévention des escarres : changement de position toutes les 2 heures, draps secs et tirés, soins d'hygiène, sonde à demeure contre les troubles urinaires. Les produits irritants sur la peau sont à proscrire.\\n\\nSource : Traumatologie Complet-2.pdf, 8.2.4.1.11 Prévenir les escarres ; Cours de chirurgie traumatique et digestif.pptx, Fractures du rachis (rôle de l'infirmier) IV. ÉTUDE DE CAS N°2\",\n       \"sourceDoc\": \"Préparation D.E (J) · J1 Chirurgie IDE\",\n       \"sourceFile\": \"J1_CHIRURGIE_IDE_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-chir-j1-ide__40\",\n       \"num\": \"41\",\n       \"type\": \"CAS_CLINIQUE\",\n       \"typeLabel\": \"Étude de cas / Cas clinique\",\n       \"partieTitle\": \"Cas clinique\",\n       \"caseTitle\": \"Cas clinique\",\n       \"caseData\": \"ÉTUDE DE CAS N°2 — En service des grands brûlés du CHU de Cocody. Vous recevez Mme Kouakou, 49 ans, 65kg, 1,68m, victime de brûlure au tronc antérieur, à la cuisse gauche et à l'organe génital. Hypertendue connue, sa TA est de 90/50 mmHg.\",\n       \"text\": \"Relever parmi les paramètres suivants les deux (2) permettant de déterminer l'indice de Baux chez le brûlé\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"A. Taille\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"B. Age\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"C. Poids\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"D. Hypertension artérielle\"\n        },\n        {\n         \"letter\": \"E\",\n         \"text\": \"E. Sexe\"\n        },\n        {\n         \"letter\": \"F\",\n         \"text\": \"F. Tension artérielle\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": true,\n       \"answer\": \"B. B. Age ; D. D. Hypertension artérielle\",\n       \"answerLetters\": [\n        \"B\",\n        \"D\"\n       ],\n       \"explanation\": \"Le cours fonde le pronostic (indice de Baux) sur l'étendue de la brûlure et l'âge du brûlé.\\n\\nSource : COURS PATHOLOGIE CHIRURGICALE SEMIOLOGIE (L1 IDE-SF), chapitre Brûlures, p. 85-101 (5-5 Pronostic, p. 92)\",\n       \"sourceDoc\": \"Préparation D.E (J) · J1 Chirurgie IDE\",\n       \"sourceFile\": \"J1_CHIRURGIE_IDE_corrige_explique.pdf\",\n       \"sourcePage\": null,\n       \"off\": true\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-chir-j1-ide__41\",\n       \"num\": \"42\",\n       \"type\": \"CAS_CLINIQUE\",\n       \"typeLabel\": \"Étude de cas / Cas clinique\",\n       \"partieTitle\": \"Cas clinique\",\n       \"caseTitle\": \"Cas clinique\",\n       \"caseData\": \"ÉTUDE DE CAS N°2 — En service des grands brûlés du CHU de Cocody. Vous recevez Mme Kouakou, 49 ans, 65kg, 1,68m, victime de brûlure au tronc antérieur, à la cuisse gauche et à l'organe génital. Hypertendue connue, sa TA est de 90/50 mmHg.\",\n       \"text\": \"Selon la table de Lund et Browder, quelle est la valeur de la surface corporelle brûlée de M. Kouakou ?\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"A. 22,5%\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"B. 23,5%\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"C. 33%\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. B. 23,5%\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"Table de Lund et Browder (adulte) : tronc antérieur 13 % + une cuisse 9,5 % + organe génital externe 1 % = 23,5 %.\\n\\nSource : Pathologie chirurgicale – Sémiologie L1 (PATHOLOGIE CHIRUR-SEMIO L1), Brûlures 2, Table de Lund et Browder\",\n       \"sourceDoc\": \"Préparation D.E (J) · J1 Chirurgie IDE\",\n       \"sourceFile\": \"J1_CHIRURGIE_IDE_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-chir-j1-ide__42\",\n       \"num\": \"43\",\n       \"type\": \"CAS_CLINIQUE\",\n       \"typeLabel\": \"Étude de cas / Cas clinique\",\n       \"partieTitle\": \"Cas clinique\",\n       \"caseTitle\": \"Cas clinique\",\n       \"caseData\": \"ÉTUDE DE CAS N°2 — En service des grands brûlés du CHU de Cocody. Vous recevez Mme Kouakou, 49 ans, 65kg, 1,68m, victime de brûlure au tronc antérieur, à la cuisse gauche et à l'organe génital. Hypertendue connue, sa TA est de 90/50 mmHg.\",\n       \"text\": \"Quelle est la valeur de l'indice de Baux (IB) pour M. Kouakou ?\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"A. 72,5\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"B. 82,5\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"C. 87,5\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"C. C. 87,5\",\n       \"answerLetters\": [\n        \"C\"\n       ],\n       \"explanation\": \"Indice de Baux = âge + SCB.\\n\\nSource : COURS PATHOLOGIE CHIRURGICALE SEMIOLOGIE (L1 IDE-SF), chapitre Brûlures, p. 85-101 (5-5 Pronostic)\",\n       \"sourceDoc\": \"Préparation D.E (J) · J1 Chirurgie IDE\",\n       \"sourceFile\": \"J1_CHIRURGIE_IDE_corrige_explique.pdf\",\n       \"sourcePage\": null,\n       \"off\": true\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-chir-j1-ide__43\",\n       \"num\": \"44\",\n       \"type\": \"CAS_CLINIQUE\",\n       \"typeLabel\": \"Étude de cas / Cas clinique\",\n       \"partieTitle\": \"Cas clinique\",\n       \"caseTitle\": \"Cas clinique\",\n       \"caseData\": \"ÉTUDE DE CAS N°2 — En service des grands brûlés du CHU de Cocody. Vous recevez Mme Kouakou, 49 ans, 65kg, 1,68m, victime de brûlure au tronc antérieur, à la cuisse gauche et à l'organe génital. Hypertendue connue, sa TA est de 90/50 mmHg.\",\n       \"text\": \"Quel est selon son Indice de Baux, le pronostic vital de M. Kouadio ?\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"A. La guérison de M. Kouadio est infiniment probable\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"B. M. Kouadio a une chance sur deux de guérir\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"C. La mort est quasi certaine pour M. Kouadio\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. B. M. Kouadio a une chance sur deux de guérir\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"Somme âge + étendue entre 50 et 100 : le brûlé a une chance sur deux de guérir. C'est le cas avec 72,5 comme avec 87,5. Remarque : L'énoncé passe de « Mme Kouakou » à « M. Kouadio » : il s'agit bien de la même patiente.\\n\\nSource : Pathologie chirurgicale – Sémiologie L1 (PATHOLOGIE CHIRUR-SEMIO L1), Brûlures 1, 5-5 Pronostic\",\n       \"sourceDoc\": \"Préparation D.E (J) · J1 Chirurgie IDE\",\n       \"sourceFile\": \"J1_CHIRURGIE_IDE_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-chir-j1-ide__44\",\n       \"num\": \"45\",\n       \"type\": \"CAS_CLINIQUE\",\n       \"typeLabel\": \"Étude de cas / Cas clinique\",\n       \"partieTitle\": \"Cas clinique\",\n       \"caseTitle\": \"Cas clinique\",\n       \"caseData\": \"ÉTUDE DE CAS N°2 — En service des grands brûlés du CHU de Cocody. Vous recevez Mme Kouakou, 49 ans, 65kg, 1,68m, victime de brûlure au tronc antérieur, à la cuisse gauche et à l'organe génital. Hypertendue connue, sa TA est de 90/50 mmHg.\",\n       \"text\": \"Parmi les propositions suivantes, relever le critère de gravité de la brûlure correspondant aux circonstances de survenue de la brûlure\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"A. Temps d'exposition\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"B. Destruction complète de la membrane basale\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"C. Brûlure des orifices naturels\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. A. Temps d'exposition\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"Les circonstances de survenue comptent parmi les critères de gravité, notamment le temps d'exposition : plus il est long, plus la brûlure est profonde.\\n\\nSource : Pathologie chirurgicale – Sémiologie L1 (PATHOLOGIE CHIRUR-SEMIO L1), Brûlures 2, IV. Critères de gravité (4.1 Circonstances de survenue)\",\n       \"sourceDoc\": \"Préparation D.E (J) · J1 Chirurgie IDE\",\n       \"sourceFile\": \"J1_CHIRURGIE_IDE_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-chir-j1-ide__45\",\n       \"num\": \"46\",\n       \"type\": \"CAS_CLINIQUE\",\n       \"typeLabel\": \"Étude de cas / Cas clinique\",\n       \"partieTitle\": \"Cas clinique\",\n       \"caseTitle\": \"Cas clinique\",\n       \"caseData\": \"ÉTUDE DE CAS N°2 — En service des grands brûlés du CHU de Cocody. Vous recevez Mme Kouakou, 49 ans, 65kg, 1,68m, victime de brûlure au tronc antérieur, à la cuisse gauche et à l'organe génital. Hypertendue connue, sa TA est de 90/50 mmHg.\",\n       \"text\": \"Dans la prise en charge d'un brûlé, les premiers secours consistent à quoi ? Choisir les deux (2) bonnes réponses.\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"A. Corriger les détresses vitales\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"B. Évaluer la surface corporelle brûlée\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"C. Couvrir la victime avec des draps propres ou stériles\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"D. Refroidir la victime avec de l'eau à 15°C pendant 15 minutes environ\"\n        },\n        {\n         \"letter\": \"E\",\n         \"text\": \"E. Administrer une ampoule de ACUPAN en IV\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": true,\n       \"answer\": \"C. C. Couvrir la victime avec des draps propres ou stériles ; D. D. Refroidir la victime avec de l'eau à 15°C pendant 15 minutes environ\",\n       \"answerLetters\": [\n        \"C\",\n        \"D\"\n       ],\n       \"explanation\": \"Premiers secours : refroidir par de l'eau à 15 °C pendant environ 15 minutes, enlever les vêtements imbibés, couvrir avec des champs stériles ou des draps propres. Évaluer la surface et l'antalgie (Acupan) viennent ensuite (bilan, analgésie).\\n\\nSource : Pathologie chirurgicale – Sémiologie L1 (PATHOLOGIE CHIRUR-SEMIO L1), Brûlures 2, V. Conduite à tenir (5.1 Premiers secours)\",\n       \"sourceDoc\": \"Préparation D.E (J) · J1 Chirurgie IDE\",\n       \"sourceFile\": \"J1_CHIRURGIE_IDE_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-chir-j1-ide__46\",\n       \"num\": \"47\",\n       \"type\": \"CAS_CLINIQUE\",\n       \"typeLabel\": \"Étude de cas / Cas clinique\",\n       \"partieTitle\": \"Cas clinique\",\n       \"caseTitle\": \"Cas clinique\",\n       \"caseData\": \"ÉTUDE DE CAS N°2 — En service des grands brûlés du CHU de Cocody. Vous recevez Mme Kouakou, 49 ans, 65kg, 1,68m, victime de brûlure au tronc antérieur, à la cuisse gauche et à l'organe génital. Hypertendue connue, sa TA est de 90/50 mmHg.\",\n       \"text\": \"Le médecin opte pour une rééquilibration hydroélectrolytique. Quelle quantité de soluté doit-on perfuser à M. Kouakou le premier jour ?\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"A. 1504 ml\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"B. 4606 ml\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"C. 6110 ml\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"C. C. 6110 ml\",\n       \"answerLetters\": [\n        \"C\"\n       ],\n       \"explanation\": \"Baxter J1 : poids × 4 × % SCB = 65 × 4 × 23,5 = 6 110 ml.\\n\\nSource : Pathologie chirurgicale – Sémiologie L1 (PATHOLOGIE CHIRUR-SEMIO L1), Brûlures 2, 5.3 Réanimation hydroélectrolytique\",\n       \"sourceDoc\": \"Préparation D.E (J) · J1 Chirurgie IDE\",\n       \"sourceFile\": \"J1_CHIRURGIE_IDE_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-chir-j1-ide__47\",\n       \"num\": \"48\",\n       \"type\": \"CAS_CLINIQUE\",\n       \"typeLabel\": \"Étude de cas / Cas clinique\",\n       \"partieTitle\": \"Cas clinique\",\n       \"caseTitle\": \"Cas clinique\",\n       \"caseData\": \"ÉTUDE DE CAS N°2 — En service des grands brûlés du CHU de Cocody. Vous recevez Mme Kouakou, 49 ans, 65kg, 1,68m, victime de brûlure au tronc antérieur, à la cuisse gauche et à l'organe génital. Hypertendue connue, sa TA est de 90/50 mmHg.\",\n       \"text\": \"Combien de flacons de solutés de remplissage de 500 ml utiliserez-vous\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"A. 12 flacons de 500 ml\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"B. 13 flacons de 500 ml\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"C. 14 flacons de 500 ml\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. B. 13 flacons de 500 ml\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"6 110 / 500 = 12,2 flacons : il faut donc 13 flacons de 500 ml.\\n\\nSource : Calcul à partir de Pathologie chirurgicale – Sémiologie L1 (PATHOLOGIE CHIRUR-SEMIO L1), Brûlures 2, 5.3\",\n       \"sourceDoc\": \"Préparation D.E (J) · J1 Chirurgie IDE\",\n       \"sourceFile\": \"J1_CHIRURGIE_IDE_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-chir-j1-ide__48\",\n       \"num\": \"49\",\n       \"type\": \"CAS_CLINIQUE\",\n       \"typeLabel\": \"Étude de cas / Cas clinique\",\n       \"partieTitle\": \"Cas clinique\",\n       \"caseTitle\": \"Cas clinique\",\n       \"caseData\": \"ÉTUDE DE CAS N°2 — En service des grands brûlés du CHU de Cocody. Vous recevez Mme Kouakou, 49 ans, 65kg, 1,68m, victime de brûlure au tronc antérieur, à la cuisse gauche et à l'organe génital. Hypertendue connue, sa TA est de 90/50 mmHg.\",\n       \"text\": \"Quel est le débit de la perfusion pour ce remplissage hydro électrolytique ?\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"A. 82 gouttes/minute\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"B. 84,86 gouttes/minute\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"C. 88,35 gouttes/minute\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. B. 84,86 gouttes/minute\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"Débit (gouttes/min) = volume (mL) × 20 gouttes / durée (min). Sur 24 heures (1 440 min) : 6 110 × 20 / 1 440 = 84,86 gouttes/minute. Remarque : Le calcul suppose une perfusion régulière sur 24 h. Le cours (règle d'Evans) indique que la moitié doit passer dans les 8 premières heures, ce qui donnerait un débit plus élevé au début.\\n\\nSource : COURS PATHOLOGIE CHIRURGICALE SEMIOLOGIE (L1 IDE-SF), chapitre Brûlures, p. 85-101 (5.3) ; formule du débit : (explication hors cours du projet)\",\n       \"sourceDoc\": \"Préparation D.E (J) · J1 Chirurgie IDE\",\n       \"sourceFile\": \"J1_CHIRURGIE_IDE_corrige_explique.pdf\",\n       \"sourcePage\": null\n      }\n     ]\n    }\n   ]\n  }\n ]\n}";
